// -----------------------------------------------------------------------------
// Author: Simone Machetti
//
// Description:
//   Self-checking testbench for the full square-BFP PE datapath, with the
//   integer square path alongside as reference and a matmul golden - the three
//   agree. Two chains run from the same dispatched operands:
//     sqr     : disp_array_{a,b}_sqr -> pe_array_sqr | pe_array_alpha_sqr |
//               pe_array_beta_sqr -> const_sqr -> acc_array_sqr -> pe_out
//     sqr_bfp : disp_array_{a,b}_sqr + disp_array_exp_{a,b}_sqr_bfp ->
//               pe_array_{alpha,beta}_sqr_bfp + pe_array_sqr_bfp ->
//               acc_array_sqr_bfp -> b_pe_out
//   The per-DP8 const_dp8_i the BFP PE needs is computed here (previews
//   const_sqr_bfp): C_cent = 16*c(nAH) + c(nAL), nAH = ~is_signed_a + ~is_signed_b,
//   nAL = 1 + ~is_signed_b, c(0/1/2)=0/512/2048; const = negated ? 2 - C_cent :
//   C_cent + 4 (the +4 cancels the two generators' per-DP8 one's-comp deferrals).
//
//   Golden = matmul X = A*B (real, or complex with 4 real products), reused from
//   tb_acc_array_sqr (matrices, pack, result reconstruction).
//
//   Pass A (equal BFP exponents): every aligner is transparent, so
//   b_pe_out === pe_out === golden - single-shot and through seed + NUM_ACC-1
//   feedback accumulation - and every BFP accumulator exponent equals the common
//   scale.
//   Pass B (per-mode BFP exponents, min-scale seed 0): sqr has no exponents, so
//   the BFP chain is checked against its own tap - the running accumulator scale
//   equals the tap scale, and b_pe_out == (seed >>> tap_exp) + NUM_ACC * (tap/2),
//   a bit-exact check of the in-loop align + /2 + running-max exponent.
//
// Parameters:
//   NUM_RAND - number of random A,B matrix pairs per mode
//   NUM_ACC  - iterations in the accumulation pass
// -----------------------------------------------------------------------------

`timescale 1 ns/1 ps

`ifndef CLK_PERIOD_NS
`define CLK_PERIOD_NS 10
`endif

