    disp_array_exp_a_sqr_bfp disp_array_exp_a_sqr_bfp_i (
        .clk_i(clk_i), .rst_ni(rst_ni), .pe_exp_a_i(pe_exp_a),
        .sel_a_i(sel_a), .zero_i(zero_dp8), .exp_a_dp8_o(exp_a_dp8)
