    disp_array_exp_b_sqr_bfp disp_array_exp_b_sqr_bfp_i (
        .clk_i(clk_i), .rst_ni(rst_ni), .pe_exp_b_i(pe_exp_b),
        .sel_b_i(sel_b), .zero_i(zero_dp8), .exp_b_dp8_o(exp_b_dp8)
    );

    pe_array_alpha_sqr_bfp pe_array_alpha_sqr_bfp_i (
        .a_dp8_i(a_dp8), .is_signed_b_i(is_signed_b),
        .alpha_sum_o(alpha_sum), .alpha_carry_o(alpha_carry)
    );

    pe_array_beta_sqr_bfp pe_array_beta_sqr_bfp_i (
        .b_dp8_i(b_dp8), .is_signed_a_i(is_signed_a), .zero_i(zero_dp8),
        .beta_sum_o(beta_sum), .beta_carry_o(beta_carry)
    );

    pe_array_sqr_bfp pe_array_sqr_bfp_i (
        .clk_i(clk_i), .rst_ni(rst_ni),
        .a_dp8_i(a_dp8), .b_dp8_i(b_dp8),
        .alpha_sum_i(alpha_sum), .alpha_carry_i(alpha_carry),
        .beta_sum_i(beta_sum), .beta_carry_i(beta_carry),
        .const_dp8_i(const_dp8), .neg_i(neg), .zero_i(zero_dp8),
        .exp_a_dp8_i(exp_a_dp8), .exp_b_dp8_i(exp_b_dp8),
        .sel_shift_i(sel_shift), .en_level_i(en_level),
        .l0_sum_o(sb_l0_sum), .l0_carry_o(sb_l0_carry), .l0_exp_o(sb_l0_exp),
        .l1_sum_o(sb_l1_sum), .l1_carry_o(sb_l1_carry), .l1_exp_o(sb_l1_exp),
        .l2_sum_o(sb_l2_sum), .l2_carry_o(sb_l2_carry), .l2_exp_o(sb_l2_exp),
        .l3_sum_o(sb_l3_sum), .l3_carry_o(sb_l3_carry), .l3_exp_o(sb_l3_exp)
    );

    acc_array_sqr_bfp acc_array_sqr_bfp_i (
        .clk_i(clk_i), .rst_ni(rst_ni),
        .l0_sum_i(sb_l0_sum), .l0_carry_i(sb_l0_carry),
        .l1_sum_i(sb_l1_sum), .l1_carry_i(sb_l1_carry),
        .l2_sum_i(sb_l2_sum), .l2_carry_i(sb_l2_carry),
        .l3_sum_i(sb_l3_sum), .l3_carry_i(sb_l3_carry),
        .l0_exp_i(sb_l0_exp), .l1_exp_i(sb_l1_exp),
        .l2_exp_i(sb_l2_exp), .l3_exp_i(sb_l3_exp),
        .acc_i(acc_bfp), .acc_exp_i(acc_exp_bfp),
        .sel_out_i(sel_out), .sel_acc_i(sel_acc), .prop_carry_i(prop_carry),
        .pe_out_o(b_pe_out), .pe_exp_o(b_pe_exp)
    );

    initial clk_i = 1'b0;
    always #(CLK_HALF) clk_i = ~clk_i;

    function automatic logic signed [15:0] rand_signed(input int width);
        logic [15:0] r;
        int pk;
        r = 16'($urandom);
        pk = $urandom % 5;
        case (width)
            4:       return (pk == 0) ? -16'sd8     : (pk == 1) ? 16'sd7     : 16'($signed(r[3:0]));
            8:       return (pk == 0) ? -16'sd128   : (pk == 1) ? 16'sd127   : 16'($signed(r[7:0]));
            default: return (pk == 0) ? -16'sd32768 : (pk == 1) ? 16'sd32767 : $signed(r);
        endcase
    endfunction

    function automatic logic signed [15:0] rand_signed_sym(input int width);
        int m;
        m = (1 << (width - 1)) - 1;
        return 16'($signed(($urandom % (2*m + 1)) - m));
    endfunction

    task automatic set_controls(input int mi);
        for (int p = 0; p < NUM_PAIR; p++) begin
            sel_a[p] = SEL_A[mi][p];
            sel_b[p] = SEL_B[mi][p];
        end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = IS_SIGNED_A[mi][i];
            is_signed_b[i] = IS_SIGNED_B[mi][i];
            zero_dp8[i]    = ZERO_I_LUT[mi][i];
        end
        neg        = NEG_I[mi];
        sel_shift  = SEL_SHIFT[mi];
        en_level   = {TAP_LEVEL[mi] >= 3, TAP_LEVEL[mi] >= 2, TAP_LEVEL[mi] >= 1};
        sel_out    = 2'(TAP_LEVEL[mi]);
        sel_const  = SEL_CONST[mi];
        mode_c     = 4'(MODE_NUM[mi]);
        prop_carry = (TAP_LEVEL[mi] >= 1);

        begin
            logic negd [0:NUM_DP8-1];
            for (int i = 0; i < NUM_DP8; i++) negd[i] = 1'b0;
            negd[2]  = NEG_I[mi][0]; negd[3]  = NEG_I[mi][1];
            negd[6]  = NEG_I[mi][2]; negd[7]  = NEG_I[mi][3];
            negd[10] = NEG_I[mi][4]; negd[11] = NEG_I[mi][5];
            for (int i = 0; i < NUM_DP8; i++) begin
                int nah, nal, ccent;
                if (ZERO_I_LUT[mi][i]) begin
                    const_dp8[i] = DP8_WIDTH'(4);
                end else begin
                    nah   = (IS_SIGNED_A[mi][i] ? 0 : 1) + (IS_SIGNED_B[mi][i] ? 0 : 1);
                    nal   = 1 + (IS_SIGNED_B[mi][i] ? 0 : 1);
                    ccent = 16*cc(nah) + cc(nal);
                    const_dp8[i] = negd[i] ? DP8_WIDTH'(2 - ccent) : DP8_WIDTH'(ccent + 4);
                end
            end
        end
    endtask

    function automatic int cc(input int n);
        return (n == 0) ? 0 : (n == 1) ? 512 : 2048;
    endfunction

    function automatic longint read_result(input int lvl, input int node);
        int hlane, llane;
        if (lvl == 0) return longint'($signed(pe_out[node]));
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;    end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;             end
        endcase
        return longint'($signed({pe_out[hlane], pe_out[llane]}));
    endfunction

    task automatic rand_matrices(input int mi);
        int M, K, N, PA, PB, cplx;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; PB = MM_DIMS[mi][4]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                A_re[m][k] = rand_signed(PA);
                A_im[m][k] = (cplx != 0) ? rand_signed(PA) : 16'sd0;
            end
        for (int k = 0; k < K; k++)
            for (int n = 0; n < N; n++) begin
                B_re[k][n] = rand_signed(PB);
                B_im[k][n] = (cplx != 0) ? rand_signed_sym(PB) : 16'sd0;
            end
    endtask

    task automatic golden(input int mi);
        int K, NOUT, m, n;
        longint re, im;
        K = MM_DIMS[mi][1]; NOUT = MM_DIMS[mi][6];
        for (int o = 0; o < NOUT; o++) begin
            m = MM_OUT[mi][o][0]; n = MM_OUT[mi][o][1];
            re = 0; im = 0;
            for (int k = 0; k < K; k++) begin
                re = re + longint'(A_re[m][k]) * longint'(B_re[k][n])
                        - longint'(A_im[m][k]) * longint'(B_im[k][n]);
                im = im + longint'(A_re[m][k]) * longint'(B_im[k][n])
                        + longint'(A_im[m][k]) * longint'(B_re[k][n]);
            end
            X_re[o] = re;
            X_im[o] = im;
        end
    endtask

    task automatic pack(input int mi);
        int M, K, N, PA, cplx, pos;
        pe_in_a = '0;
        pe_in_b = '0;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                pos = MM_RE_A[mi][m][k] & 255;
                if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][7:0];
                if (PA == 16) begin
                    pos = (MM_RE_A[mi][m][k] >> 8) & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][15:8];
                end
                if (cplx != 0) begin
                    pos = MM_IM_A[mi][m][k] & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][7:0];
                    if (PA == 16) begin
                        pos = (MM_IM_A[mi][m][k] >> 8) & 255;
                        if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][15:8];
                    end
                end
            end
        if (MODE_NUM[mi] == 12)
            pack_b_c16c16();
        else
            for (int k = 0; k < K; k++)
                for (int n = 0; n < N; n++)
                    for (int p = 0; p < 4; p++) begin
                        pos = (MM_RE_B[mi][k][n] >> (8*p)) & 255;
                        if (pos != 255) pe_in_b[pos*4 +: 4] = B_re[k][n][p*4 +: 4];
                        if (cplx != 0) begin
                            pos = (MM_IM_B[mi][k][n] >> (8*p)) & 255;
                            if (pos != 255) pe_in_b[pos*4 +: 4] = B_im[k][n][p*4 +: 4];
                        end
                    end
    endtask

    task automatic put_b16(input logic [15:0] v, input int blk_hi, input int blk_lo, input int lane);
        pe_in_b[(blk_hi*16 + 8 + lane)*4 +: 4] = v[15:12];
        pe_in_b[(blk_hi*16     + lane)*4 +: 4] = v[11:8];
        pe_in_b[(blk_lo*16 + 8 + lane)*4 +: 4] = v[7:4];
        pe_in_b[(blk_lo*16     + lane)*4 +: 4] = v[3:0];
    endtask

    task automatic pack_b_c16c16;
        for (int k = 0; k < 4; k++) begin
            put_b16( B_re[k][0], 0, 1, k);
            put_b16(-B_im[k][0], 0, 1, 4 + k);
            put_b16( B_im[k][0], 2, 3, k);
            put_b16( B_re[k][0], 2, 3, 4 + k);
        end
    endtask

    task automatic compare(input int mi);
        int NOUT, lvl, rn, in;
        longint r;
        NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
        for (int o = 0; o < NOUT; o++) begin
            rn = MM_OUT[mi][o][2];
            in = MM_OUT[mi][o][3];
            r = read_result(lvl, rn);
            if (r !== X_re[o]) begin
                err = err + 1;
                $display("mode %0d output %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, X_re[o], r);
            end
            if (in >= 0) begin
                r = read_result(lvl, in);
                if (r !== X_im[o]) begin
                    err = err + 1;
                    $display("mode %0d output %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, X_im[o], r);
                end
            end
        end
    endtask

    task automatic clear_acc;
        for (int j = 0; j < NUM_LANE; j++) acc_word[j] = '0;
    endtask

    task automatic set_acc(input int lvl, input int node, input longint val);
        int hlane, llane;
        if (lvl == 0) begin
            acc_word[node] = val[ACC_W-1:0];
            return;
        end
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;   end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;            end
        endcase
        acc_word[hlane] = val[2*ACC_W-1:ACC_W];
        acc_word[llane] = val[ACC_W-1:0];
    endtask

    function automatic int ebias(input int base);
        int d;
        case ($urandom_range(0, 7))
            0: d = 0; 1: d = 1; 2: d = 7; 3: d = 8; 4: d = 27; 5: d = 28; 6: d = 56;
            default: d = int'($urandom_range(0, 63));
        endcase
        if ($urandom_range(0, 1) == 1) d = -d;
        d = base + d;
        if (d < 0) d = 0;
        if (d > 63) d = 63;
        return d;
    endfunction

    task automatic set_exps(input int mi, input bit equal);
        int base;
        int ga [0:3];
        int gb [0:7];
        logic [5:0] ea [0:3];
        logic [5:0] eb [0:7];
        base = int'($urandom_range(0, 63));
        for (int g = 0; g < 4; g++) ga[g] = equal ? base : ebias(base);
        for (int g = 0; g < 8; g++) gb[g] = equal ? base : ebias(base);
        for (int blk = 0; blk < 4; blk++) ea[blk] = 6'(ga[EGRP_A[mi][blk]]);
        for (int h = 0; h < 8; h++)      eb[h]   = 6'(gb[EGRP_B[mi][h]]);
        for (int blk = 0; blk < 4; blk++) begin
            pe_exp_a[blk*EXP_IN_WIDTH +: EXP_IN_WIDTH]           = ea[blk];
            pe_exp_b[blk*CHK_WIDTH+EXP_IN_WIDTH +: EXP_IN_WIDTH] = eb[2*blk];
            pe_exp_b[blk*CHK_WIDTH +: EXP_IN_WIDTH]              = eb[2*blk+1];
        end
        for (int p = 0; p < NUM_PAIR; p++) begin
            gold_exp_a[2*p]   = zero_dp8[2*p]   ? '0 : EXP_WIDTH'(ea[SEL_A[mi][p]]);
            gold_exp_b[2*p]   = zero_dp8[2*p]   ? '0 : EXP_WIDTH'(eb[int'(SEL_B[mi][p])*2]);
            gold_exp_a[2*p+1] = zero_dp8[2*p+1] ? '0 : EXP_WIDTH'(ea[SEL_A[mi][p]]);
            gold_exp_b[2*p+1] = zero_dp8[2*p+1] ? '0 : EXP_WIDTH'(eb[int'(SEL_B[mi][p])*2+1]);
        end
        for (int i = 0; i < NUM_DP8; i++)
            exp_dp8_g[i] = gold_exp_a[i] + gold_exp_b[i];
    endtask

    function automatic bit insub(input int d, input int lvl, input int node);
        int n;
        n = 2*(d/4) + (d%2);
        case (lvl)
            0:       return (n == node);
            1:       return (n/2 == node);
            2:       return (n/4 == node);
            default: return 1'b1;
        endcase
    endfunction

    function automatic logic [EXP_WIDTH-1:0] egold(input int lvl, input int node);
        logic [EXP_WIDTH-1:0] e;
        e = '0;
        for (int d = 0; d < NUM_DP8; d++)
            if (insub(d, lvl, node) && exp_dp8_g[d] > e) e = exp_dp8_g[d];
        return e;
    endfunction

    task automatic clear_acc_bfp;
        for (int j = 0; j < NUM_LANE; j++) begin acc_bfp[j] = '0; acc_exp_bfp[j] = '0; end
    endtask

    task automatic set_acc_bfp(input int lvl, input int node, input longint val, input logic [EXP_WIDTH-1:0] e);
        int hlane, llane;
        if (lvl == 0) begin acc_bfp[node] = val[ACC_W-1:0]; acc_exp_bfp[node] = e; return; end
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;   end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;            end
        endcase
        acc_bfp[hlane] = val[2*ACC_W-1:ACC_W]; acc_bfp[llane] = val[ACC_W-1:0];
        acc_exp_bfp[hlane] = e;                acc_exp_bfp[llane] = e;
    endtask

    function automatic longint read_result_bfp(input int lvl, input int node);
        int hlane, llane;
        if (lvl == 0) return longint'($signed(b_pe_out[node]));
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;   end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;            end
        endcase
        return longint'($signed({b_pe_out[hlane], b_pe_out[llane]}));
    endfunction

    function automatic logic [EXP_WIDTH-1:0] read_exp_bfp(input int lvl, input int node);
        int hlane;
        if (lvl == 0) return b_pe_exp[node];
        case (lvl)
            1:       hlane = 2*node;
            2:       hlane = (node==0)?2:6;
            default: hlane = 6;
        endcase
        return b_pe_exp[hlane];
    endfunction

    function automatic longint resolve_tap_bfp(input int lvl, input int node);
        case (lvl)
            0:       return longint'($signed(sb_l0_sum[node])) + longint'($signed(sb_l0_carry[node]));
            1:       return longint'($signed(sb_l1_sum[node])) + longint'($signed(sb_l1_carry[node]));
            2:       return longint'($signed(sb_l2_sum[node])) + longint'($signed(sb_l2_carry[node]));
            default: return longint'($signed(sb_l3_sum))       + longint'($signed(sb_l3_carry));
        endcase
    endfunction

    function automatic longint seed_floor(input longint v, input int e);
        int ee;
        ee = (e > 63) ? 63 : e;
        return v >>> ee;
    endfunction

    longint acc_seed    [0:MAXO-1];
    longint acc_seed_im [0:MAXO-1];

    initial begin
        int err0, NOUT, lvl, rn, in;
        longint gexp, tapval;
        logic [EXP_WIDTH-1:0] e_re, e_im;
        $display("\nStarting acc_array_sqr_bfp (square-BFP chain vs integer square vs matmul), %0d modes x %0d random...\n",
                 NUM_MODE, NUM_RAND);
`ifdef VCD
        $dumpfile("activity.vcd");
        $dumpvars(0, tb_acc_array_sqr_bfp.acc_array_sqr_bfp_i);
`endif

        rst_ni  = 1'b0;
        pe_in_a = '0; pe_in_b = '0; pe_exp_a = '0; pe_exp_b = '0;
        for (int p = 0; p < NUM_PAIR; p++) begin sel_a[p] = '0; sel_b[p] = '0; end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = 1'b0; is_signed_b[i] = 1'b0; zero_dp8[i] = 1'b0;
            const_dp8[i] = '0; gold_exp_a[i] = '0; gold_exp_b[i] = '0; exp_dp8_g[i] = '0;
        end
        neg = '0; sel_const = '0; mode_c = '0;
        sel_shift = '0; en_level = '1; sel_out = '0; sel_acc = 1'b0; prop_carry = 1'b0;
        clear_acc(); clear_acc_bfp();
        err = 0; npass = 0;
        repeat (3) @(posedge clk_i);
        rst_ni = 1'b1;

        $display("Pass A - equal exponents, single-shot (matmul == sqr == sqr_bfp):");
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            clear_acc(); clear_acc_bfp();
            sel_acc = 1'b0;
            err0 = err;
            for (int t = 0; t < NUM_RAND; t++) begin
                rand_matrices(mi); golden(mi); pack(mi); set_exps(mi, 1'b1);
                repeat (3) @(posedge clk_i);
                #(T_SETTLE);
                compare(mi);
                NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
                for (int o = 0; o < NOUT; o++) begin
                    rn = MM_OUT[mi][o][2]; in = MM_OUT[mi][o][3];
                    if (read_result_bfp(lvl, rn) !== X_re[o]) begin
                        err++; $display("  A m%0d o%0d Re: gold=%0d bfp=%0d", MODE_NUM[mi], o, X_re[o], read_result_bfp(lvl,rn));
                    end
                    if (read_exp_bfp(lvl, rn) !== egold(lvl, rn)) begin
                        err++; $display("  A m%0d o%0d Re exp: gold=%0d bfp=%0d", MODE_NUM[mi], o, egold(lvl,rn), read_exp_bfp(lvl,rn));
                    end
                    if (in >= 0)
                        if (read_result_bfp(lvl, in) !== X_im[o]) begin
                            err++; $display("  A m%0d o%0d Im: gold=%0d bfp=%0d", MODE_NUM[mi], o, X_im[o], read_result_bfp(lvl,in));
                        end
                end
            end
            if (err == err0) begin npass++; $display("  mode %0d: PASS", MODE_NUM[mi]); end
            else $display("  mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

        $display("\nPass A - equal exponents, accumulation (seed + %0d feedback), matmul == sqr == sqr_bfp:", NUM_ACC);
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            rand_matrices(mi); golden(mi); pack(mi); set_exps(mi, 1'b1);
            NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
            clear_acc(); clear_acc_bfp();
            for (int o = 0; o < NOUT; o++) begin
                acc_seed[o] = longint'(rand_signed(16));
                set_acc(lvl, MM_OUT[mi][o][2], acc_seed[o]);
                set_acc_bfp(lvl, MM_OUT[mi][o][2], acc_seed[o], egold(lvl, MM_OUT[mi][o][2]));
                if (MM_OUT[mi][o][3] >= 0) begin
                    acc_seed_im[o] = longint'(rand_signed(16));
                    set_acc(lvl, MM_OUT[mi][o][3], acc_seed_im[o]);
                    set_acc_bfp(lvl, MM_OUT[mi][o][3], acc_seed_im[o], egold(lvl, MM_OUT[mi][o][3]));
                end
            end
            sel_acc = 1'b0;
            repeat (3) @(posedge clk_i); #(T_SETTLE);
            for (int it = 1; it < NUM_ACC; it++) begin sel_acc = 1'b1; @(posedge clk_i); end
            #(T_SETTLE);
            err0 = err;
            for (int o = 0; o < NOUT; o++) begin
                rn = MM_OUT[mi][o][2]; in = MM_OUT[mi][o][3];
                gexp = acc_seed[o] + NUM_ACC * X_re[o];
                if (read_result(lvl, rn)     !== gexp) begin err++; $display("  Aacc m%0d o%0d Re sqr: gold=%0d got=%0d", MODE_NUM[mi], o, gexp, read_result(lvl,rn)); end
                if (read_result_bfp(lvl, rn) !== gexp) begin err++; $display("  Aacc m%0d o%0d Re bfp: gold=%0d got=%0d", MODE_NUM[mi], o, gexp, read_result_bfp(lvl,rn)); end
                if (in >= 0) begin
                    gexp = acc_seed_im[o] + NUM_ACC * X_im[o];
                    if (read_result(lvl, in)     !== gexp) begin err++; $display("  Aacc m%0d o%0d Im sqr: gold=%0d got=%0d", MODE_NUM[mi], o, gexp, read_result(lvl,in)); end
                    if (read_result_bfp(lvl, in) !== gexp) begin err++; $display("  Aacc m%0d o%0d Im bfp: gold=%0d got=%0d", MODE_NUM[mi], o, gexp, read_result_bfp(lvl,in)); end
                end
            end
            if (err == err0) $display("  acc mode %0d: PASS", MODE_NUM[mi]);
            else $display("  acc mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

        $display("\nPass B - distinct exponents, min-scale seed (bfp: (seed>>>e) + N*(tap/2)):");
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            err0 = err;
            for (int t = 0; t < NUM_RAND; t++) begin
                rand_matrices(mi); pack(mi); set_exps(mi, 1'b0);
                NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
                clear_acc_bfp();
                for (int o = 0; o < NOUT; o++) begin
                    acc_seed[o] = longint'(rand_signed(16));
                    set_acc_bfp(lvl, MM_OUT[mi][o][2], acc_seed[o], '0);
                    if (MM_OUT[mi][o][3] >= 0) begin
                        acc_seed_im[o] = longint'(rand_signed(16));
                        set_acc_bfp(lvl, MM_OUT[mi][o][3], acc_seed_im[o], '0);
                    end
                end
                sel_acc = 1'b0;
                repeat (3) @(posedge clk_i); #(T_SETTLE);
                for (int it = 1; it < NUM_ACC; it++) begin sel_acc = 1'b1; @(posedge clk_i); end
                #(T_SETTLE);
                for (int o = 0; o < NOUT; o++) begin
                    rn = MM_OUT[mi][o][2]; in = MM_OUT[mi][o][3];
                    e_re   = egold(lvl, rn);
                    tapval = resolve_tap_bfp(lvl, rn);
                    gexp   = ( ( ((acc_seed[o]*2) >>> int'(e_re)) + tapval ) >>> 1 )
                             + (NUM_ACC - 1) * ( tapval >>> 1 );
                    if (read_result_bfp(lvl, rn) !== gexp) begin
                        err++; $display("  B m%0d o%0d Re: gold=%0d bfp=%0d (e=%0d 2P=%0d)", MODE_NUM[mi], o, gexp, read_result_bfp(lvl,rn), e_re, tapval);
                    end
                    if (read_exp_bfp(lvl, rn) !== e_re) begin
                        err++; $display("  B m%0d o%0d Re exp: gold=%0d bfp=%0d", MODE_NUM[mi], o, e_re, read_exp_bfp(lvl,rn));
                    end
                    if (in >= 0) begin
                        e_im   = egold(lvl, in);
                        tapval = resolve_tap_bfp(lvl, in);
                        gexp   = ( ( ((acc_seed_im[o]*2) >>> int'(e_im)) + tapval ) >>> 1 )
                                 + (NUM_ACC - 1) * ( tapval >>> 1 );
                        if (read_result_bfp(lvl, in) !== gexp) begin
                            err++; $display("  B m%0d o%0d Im: gold=%0d bfp=%0d", MODE_NUM[mi], o, gexp, read_result_bfp(lvl,in));
                        end
                    end
                end
            end
            if (err == err0) $display("  mode %0d: PASS", MODE_NUM[mi]);
            else $display("  mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

`ifdef VCD
        $dumpoff;
`endif
        $display("\nacc_array_sqr_bfp: %0d/%0d Pass-A single-shot modes passed, %0d total mismatches\n",
                 npass, NUM_MODE, err);
        $finish;
    end

endmodule
